mapper.select:
WHERE 1 = 1 AND U.APLY_STTS_CD = #{aplySttsCd}
AND (U.USER_ID LIKE CONCAT('%', #{searchKeyword}, '%') OR U.USER_NM LIKE CONCAT('%', #{searchKeyword}, '%') OR U.OGDP_BZENTY_NM LIKE CONCAT('%', #{searchKeyword}, '%') OR U.DEPT_NM LIKE CONCAT('%', #{searchKeyword}, '%'))
ORDER BY U.APLY_DT DESC, U.APLY_NO DESC

mapper.update:
UPDATE user_acnt_aply_info
   SET APLY_STTS_CD = 'REJECTED', RFSL_RSN = #{rfslRsn}
 WHERE APLY_NO = #{aplyNo} AND APLY_STTS_CD = 'WAITING'
